# Red-team review computations for TASK-20260928-fa61f4 (REVIEW-AUXIN-20260928-104724).
# Zero experiment runs: no RUN-*, no Cheon algorithm, no [x^i]P, no driver.py.
# Reads the snapshot bytes (bfbc573af2) of the producer files and the hash-bound layers.
import hashlib, json, re, subprocess, sys, time, itertools, collections, datetime
import yaml, mpmath, sympy
from sympy import isprime, nextprime, divisors

ROOT = '/Volumes/SSD990/crypto-autoresearcher/.worktrees/ecdlp-9225d2-revise-20260927'
SNAP = 'bfbc573af291bc2bd143844f23e110a8888667cc'
A = 'experiments/EXP-AUXIN-7e2e3d/amendments/'
B = 'coordination/goals/GOAL-AUXIN-a93442/batches/BATCH-104724/'
OUT = {}
H = lambda b: hashlib.sha256(b if isinstance(b, bytes) else b.encode()).hexdigest()
now = lambda: datetime.datetime.now(datetime.timezone.utc).isoformat()
OUT['started_utc'] = now()

def snap(path):
    return subprocess.run(['git', '-C', ROOT, 'show', f'{SNAP}:{path}'], capture_output=True, check=True).stdout

# ---------------------------------------------------------------- custody
receipt = json.loads(snap(B + 'archives/TASK-20260928-e46f76/snapshot-receipt.json'))
cust = {'snapshot_commit': SNAP, 'files': []}
files = {
    A + 'AMD-20260928-gated.yaml': receipt['source_path_sha256'][A + 'AMD-20260928-gated.yaml'],
    B + 'design/TASK-20260928-9a1ec0/design-report.yaml': receipt['source_path_sha256'][B + 'design/TASK-20260928-9a1ec0/design-report.yaml'],
    A + 'AMD-20260927-narrow.yaml': 'ccd11216c3250d9ab69fafa7f4252a872704772a2091fc70989a198d1ca11dcd',
    A + 'AMD-20260926-typed.yaml': '3c57978c91b632226c0e0543913f8a122bb16d121b0a308254b1c99cedeeaad6',
    'experiments/EXP-AUXIN-7e2e3d/specification.yaml': '1f803aa0a535e4c0a321dfcb3851b89cbd4cae23596ad70e1aa1fd1b06639fbc',
}
for p, want in files.items():
    b = snap(p); wt = open(f'{ROOT}/{p}', 'rb').read()
    cust['files'].append({'path': p, 'expected': want, 'at_snapshot': H(b), 'working_tree': H(wt),
                          'match': H(b) == want == H(wt)})
cust['receipt_sha256_at_snapshot'] = H(snap(B + 'archives/TASK-20260928-e46f76/snapshot-receipt.json'))
cust['all_match'] = all(f['match'] for f in cust['files'])
OUT['custody'] = cust

g = yaml.safe_load(snap(A + 'AMD-20260928-gated.yaml'))['amendment']
n = yaml.safe_load(snap(A + 'AMD-20260927-narrow.yaml'))['amendment']
t = yaml.safe_load(snap(A + 'AMD-20260926-typed.yaml'))['amendment']
v1 = yaml.safe_load(snap('experiments/EXP-AUXIN-7e2e3d/specification.yaml'))['experiment']
dr = yaml.safe_load(snap(B + 'design/TASK-20260928-9a1ec0/design-report.yaml'))['design_report']
OUT['draft_states_hashes'] = {'narrow': g['incorporates_by_hash']['sha256'], 'typed': g['incorporates_by_hash']['through_it']['sha256'],
                              'v1': g['incorporates_by_hash']['v1']['sha256'],
                              'equal_to_plan_and_bytes': g['incorporates_by_hash']['sha256'] == files[A + 'AMD-20260927-narrow.yaml']
                              and g['incorporates_by_hash']['through_it']['sha256'] == files[A + 'AMD-20260926-typed.yaml']
                              and g['incorporates_by_hash']['v1']['sha256'] == files['experiments/EXP-AUXIN-7e2e3d/specification.yaml']}

# ---------------------------------------------------------------- spans (RJ3 v)
def tget(obj, path):
    o = obj
    for seg in re.findall(r'[^.\[\]]+|\[[^\]]+\]', path):
        if seg.startswith('['):
            k = seg[1:-1]; o = [x for x in o if isinstance(x, dict) and x.get('id') == k][0]
        elif seg.startswith('gates item '):
            o = o['gates'][int(seg.split()[-1]) - 1]
        else:
            o = o[seg]
    return o
cb = [c for c in t['controls'] if c['id'] == 'C-BOUND'][0]
st = {s['id']: s for s in cb['states']}
gval = {'G-GATE1': cb['gates'][0], 'G-BND1': st['BND-1']['expected'], 'G-BND3': st['BND-3']['expected'],
        'G-Q011': t['conventions']['Q0-11'], 'G-CPL': n['corrective']['declared_not_superseded'][0]['declaration'],
        'G-WII': n['incorporates']['what_is_incorporated'], 'G-ENV': n['envelope_not_incorporated']['rule']}
spans = []
for r in g['gated_span_rules']:
    v = gval[r['id']]; i = v.find(r['from']); j = v.find(r['through'], i); sp = v[i:j + len(r['through'])]
    spans.append({'id': r['id'], 'layer_file': r['file'], 'from_occurrences': v.count(r['from']),
                  'sha256': H(sp), 'declared': r['replaced_span_sha256'], 'match': H(sp) == r['replaced_span_sha256'],
                  'resulting_text': v[:i] + r['replacement'] + v[j + len(r['through']):]})
for r in n['span_rules']:
    v = tget(t, r['field']); i = v.find(r['from']); j = v.find(r['through'], i); sp = v[i:j + len(r['through'])]
    spans.append({'id': r['id'], 'layer_file': 'narrow on typed', 'from_occurrences': v.count(r['from']),
                  'sha256': H(sp), 'declared': r['replaced_span_sha256'], 'match': H(sp) == r['replaced_span_sha256']})
pl = [c for c in t['controls'] if c['id'] == 'C-PLANT-PL'][0]['declared_properties']
q5 = "Hence the plus minimiser is D_L, uniquely, and e_plus - F_plus is below 10^-6 by a wide margin."
q3 = v1['tail_checks'][0]
OUT['spans'] = {'rules': spans, 'all_match_and_unique': all(s['match'] and s['from_occurrences'] == 1 for s in spans),
                'ER-5_quote': {'occurrences_in_typed_value': pl.count(q5), 'sha256': H(q5),
                               'declared': 'a0fad262cb56745a8de22412c1ebc03671c8daa40dfaa23992cd98e53af19bff'},
                'ER-3_quote': {'v1_value_equals_quote': q3 in g['corrective']['falsification_condition_mapping_fc6']['outcome'],
                               'sha256': H(q3), 'declared': '26b53f8995afb04335a24612dcf48e736a2dd0e3d72d5f9b6b440b1a13cc5e52'}}

# ---------------------------------------------------------------- table totality (RJ3 ii)
KEYS = ('id', 'name', 'state', 'case', 'fc', 'item', 'field', 'path', 'kind')
L = {'v1': v1, 'typed': t, 'narrow': n, 'gated': g}
def walk(o, segs, keyleaf=False):
    if isinstance(o, dict) and o:
        for k, v in o.items():
            yield from walk(v, segs + [{'.' + str(k)}], k in KEYS)
    elif isinstance(o, list) and o:
        for i, v in enumerate(o):
            al = {f' item {i+1}'}
            if isinstance(v, dict):
                for kk in KEYS:
                    if kk in v and isinstance(v[kk], (str, int)): al.add(f'[{v[kk]}]')
            yield from walk(v, segs + [al])
    else:
        yield segs, keyleaf
def aliases(segs):
    out = ['']
    for s in segs:
        out = [o + a for o in out for a in s][:128]
    return [o[1:] if o.startswith('.') else o for o in out]
rows = []
for r in g['governing_text_table']:
    ly, _, p = r['field'].partition(':'); mod = None
    m = re.match(r'(.*?) (spans? [A-Z0-9-]+(?:, [A-Z0-9-]+)*|outside spans? [A-Z0-9-]+(?:, [A-Z0-9-]+)*|except .*)$', p)
    if m: p, mod = m.group(1), m.group(2)
    rows.append((ly, p, mod, r['layer'], r['field']))
def covers(rp, leaf):
    return leaf == rp or leaf.startswith(rp + '.') or leaf.startswith(rp + '[') or leaf.startswith(rp + ' item')
tot = collections.Counter(); uncovered_nonkey = []; key_uncovered = 0; multi = []
for ly in ('v1', 'typed', 'narrow', 'gated'):
    for segs, keyleaf in walk(L[ly], []):
        al = aliases(segs)
        hits = [r for r in rows if r[0] == ly and any(covers(r[1], a) for a in al)]
        if not hits:
            if keyleaf: key_uncovered += 1
            else: uncovered_nonkey.append(f'{ly}:{al[0]}')
            continue
        mx = max(len(h[1]) for h in hits); top = [h for h in hits if len(h[1]) == mx]
        mods = [h[2] for h in top]
        if len(top) == 1 and mods == [None]: tot['single_row'] += 1
        elif all(m is not None for m in mods) and any(m.startswith('outside') or m.startswith('except') for m in mods): tot['span_or_except_partition'] += 1
        elif len(hits) > len(top) and any((h[2] or '').startswith('except') for h in hits): tot['span_or_except_partition'] += 1
        else: multi.append((f'{ly}:{al[0]}', [h[4] for h in hits]))
OUT['table_totality'] = {'rows': len(rows), 'leaves_single_row': tot['single_row'],
                         'leaves_in_declared_partition': tot['span_or_except_partition'],
                         'identifier_key_leaves_without_own_row': key_uncovered,
                         'non_key_leaves_without_row': uncovered_nonkey, 'leaves_with_two_unpartitioned_rows': multi,
                         'layer_counts': dict(collections.Counter(r['layer'] for r in g['governing_text_table'])),
                         'design_report_counts_this_file': dr['governing_text_table_counts']['this_file']['by_layer']}
N = {r['field']: r['layer'] for r in n['governing_text_table']}; G = {r['field']: r['layer'] for r in g['governing_text_table']}
nm = {'v1': 'v1', 'refused-typed-by-hash': 'typed-by-hash', 'corrective': 'narrow-by-hash'}
OUT['table_diff_narrow_to_gated'] = {
    'common_rows': len(set(N) & set(G)),
    'layer_changed': [(f, N[f], G[f]) for f in sorted(set(N) & set(G)) if nm.get(N[f], N[f]) != G[f]],
    'narrow_rows_split_or_removed': sorted(set(N) - set(G)),
    'new_typed_or_v1_rows': sorted(f for f in set(G) - set(N) if f.split(':')[0] in ('typed', 'v1', 'file'))}
adds = []
for ly in ('narrow', 'gated'):
    for segs, _ in walk(L[ly], []):
        a = aliases(segs)[0]
        if a.endswith('adds_to'): adds.append(f'{ly}:{a}')
OUT['path_additions'] = {'adds_to_entries_found': len(adds), 'path_additions_entries': len(g['path_additions']),
                         'addition_members_listed': sum(len(e['additions']) for e in g['path_additions'])}

# ---------------------------------------------------------------- reader search (RJ3 iii)
def leaves_text(ly):
    for segs, _ in walk(L[ly], []):
        p = aliases(segs)[0]
        o = L[ly]
        yield p
pat_ref = re.compile(r'(AMD-[\w-]+|DEC-\d+-\w+|VAL-\d+-\w+|RT-\d+-\w+|CORR-\d+-\w+|[\w./-]+\.(?:yaml|json|pdf|py))')
OUT['narrow_span_replacements_referencing_other_files'] = [
    {'span': s['id'], 'field': s['field'], 'refs': sorted(set(pat_ref.findall(s['replacement'])))}
    for s in n['span_rules'] if pat_ref.findall(s['replacement'])]
mapped = ' || '.join(r['clause'] for r in dr['reader_map'])
OUT['reader_map_entries'] = len(dr['reader_map'])
OUT['reader_map_classification_counts'] = dict(collections.Counter(r['classification'] for r in dr['reader_map']))
OUT['reader_map_mentions'] = {k: (k in mapped) for k in ['BN-K', 'rows[BN254-r]', 'TP-FOUR', 'MAN-DIRTY', 'ECM-PROV',
                                                         'invalidation_rules item 9', 'metrics.primary item 4',
                                                         'definitions.bins', 'stopping_rules item 13']}

# ---------------------------------------------------------------- bins (typed definitions.bins + narrow BINS-EXACT + narrow bin_by_status)
mpmath.mp.dps = 160
TAU = mpmath.mpf(10) ** -45
Q, TQ = mpmath.mpf(1) / 4, mpmath.mpf(3) / 4
def flag(s): return abs(s - Q) <= TAU or abs(s - TQ) <= TAU
def exact_bin(s):
    if flag(s): return 'INTERMEDIATE' if abs(s - TQ) <= TAU else 'NEAR_CEILING'
    if s >= TQ + TAU: return 'NEAR_FLOOR'
    if s <= Q - TAU: return 'NEAR_CEILING'
    return 'INTERMEDIATE'
def bin_fields(status, s):
    if status == 'EXACT':
        b = exact_bin(s); return {'bin': b, 'bin_at_least': b, 'boundary_flag': flag(s)}
    if status == 'BOUND':
        f = flag(s)
        if (not f) and s >= TQ + TAU: return {'bin': 'NEAR_FLOOR', 'bin_at_least': 'NEAR_FLOOR', 'boundary_flag': f}
        return {'bin': 'UNDETERMINED', 'bin_at_least': exact_bin(s), 'boundary_flag': f}
    return {'bin': None, 'bin_at_least': None, 'boundary_flag': None}
lg = lambda x: mpmath.log(x, 2)
def T(b, m, d): return mpmath.sqrt(mpmath.mpf(m) / d) + (mpmath.sqrt(d) if b == 'minus' else d)
def Fb(b, r):
    return (1 + lg(r - 1) / 4) / lg(r) if b == 'minus' else (lg(3) - mpmath.mpf(2) / 3 + lg(r + 1) / 3) / lg(r)
def Cb(b, r):
    m = r - 1 if b == 'minus' else r + 1
    return lg(mpmath.sqrt(m) + 1) / lg(r)
def e_of(b, r, d):
    m = r - 1 if b == 'minus' else r + 1
    return lg(T(b, m, d)) / lg(r)
def depth(b, r, e): return (Cb(b, r) - e) / (Cb(b, r) - Fb(b, r))
def argmin_ties(b, r, cand):
    vals = [(e_of(b, r, d), d) for d in cand]; es = min(v[0] for v in vals)
    tied = sorted(d for e, d in vals if e - es <= mpmath.mpf(10) ** -100 * es)
    return tied[0], es

# ---------------------------------------------------------------- C-BOUND analytic stand-ins (no control integer is built)
# BND-1: m = r-1, witness D or 2u within relative delta of sqrt(m); BND-3: m = r+1, witness 2d with d within relative delta of (m/4)^(1/3).
def bnd1_depth(logm, delta):
    m = mpmath.mpf(2) ** logm; r = m + 1
    D = mpmath.sqrt(m) * (1 + delta)
    e = lg(mpmath.sqrt(m / D) + mpmath.sqrt(D)) / lg(r)
    return depth('minus', r, e)
def bnd2_depth(logm):
    m = mpmath.mpf(2) ** logm; r = m + 1
    e = lg(mpmath.sqrt(m / 2) + mpmath.sqrt(2)) / lg(r)
    return depth('minus', r, e)
def bnd3_depth(logm, delta):
    m = mpmath.mpf(2) ** logm; r = m - 1
    d = (m / 4) ** (mpmath.mpf(1) / 3) * (1 + delta); w = 2 * d
    e = lg(mpmath.sqrt(m / w) + w) / lg(r)
    return depth('plus', r, e)
model = []
for logm in (255, 256):
    for dl in (mpmath.mpf(0), mpmath.mpf(2) ** -37, -mpmath.mpf(2) ** -37):
        s = bnd1_depth(logm, dl); model.append({'state': 'BND-1 stand-in', 'log2_m': logm, 'rel_offset': mpmath.nstr(dl, 5),
                                                 'depth': mpmath.nstr(s, 20), **bin_fields('BOUND', s)})
    s = bnd2_depth(logm); model.append({'state': 'BND-2 stand-in', 'log2_m': logm, 'depth': mpmath.nstr(s, 20), **bin_fields('BOUND', s)})
    for dl in (mpmath.mpf(0), mpmath.mpf(2) ** -60, -mpmath.mpf(2) ** -60):
        s = bnd3_depth(logm, dl); model.append({'state': 'BND-3 stand-in', 'log2_m': logm, 'rel_offset': mpmath.nstr(dl, 5),
                                                 'depth': mpmath.nstr(s, 20), **bin_fields('BOUND', s)})
OUT['c_bound_analytic_stand_ins'] = {
    'note': 'Synthetic magnitudes of the declared shapes (why_fixed_in_advance), not the recipe integers. Checks that the bins '
            'the gated expected blocks state equal what narrow corrective.bin_by_status gives on every admissible depth.',
    'rows': model}

# ---------------------------------------------------------------- evaluators and gate 1 / N4 (RJ3 iv, PTM-F, PTM-G)
EXPECTED_NARROW = {  # fields gate 1 compares under narrow ("bin_at_least (where stated)")
    'BND-1': {'status': 'BOUND', 'bin': 'NEAR_FLOOR', 'boundary_flag': False},
    'BND-2': {'status': 'BOUND', 'bin': 'UNDETERMINED', 'bin_at_least': 'NEAR_CEILING', 'boundary_flag': False},
    'BND-3': {'status': 'BOUND', 'bin': 'NEAR_FLOOR', 'boundary_flag': False}}
EXPECTED_GATED = {k: dict(v) for k, v in EXPECTED_NARROW.items()}
EXPECTED_GATED['BND-1']['bin_at_least'] = 'NEAR_FLOOR'; EXPECTED_GATED['BND-3']['bin_at_least'] = 'NEAR_FLOOR'
FIXED_VALUE = {  # "the value this text fixes" (N4), from narrow corrective.bin_by_status on the declared depths
    'BND-1': {'status': 'BOUND', 'bin': 'NEAR_FLOOR', 'bin_at_least': 'NEAR_FLOOR', 'boundary_flag': False},
    'BND-2': {'status': 'BOUND', 'bin': 'UNDETERMINED', 'bin_at_least': 'NEAR_CEILING', 'boundary_flag': False},
    'BND-3': {'status': 'BOUND', 'bin': 'NEAR_FLOOR', 'bin_at_least': 'NEAR_FLOOR', 'boundary_flag': False}}
MISSING = object()
def gate1(expected, ret):
    return all(ret.get(k, MISSING) == v for k, v in expected.items())
def n4(ret, state):
    return any(ret.get(k, MISSING) != v for k, v in FIXED_VALUE[state].items())
def outcomes(expected, retA, retB, state):
    gA, gB = gate1(expected, retA), gate1(expected, retB)
    sr10 = (not gA) or (not gB)          # typed stopping_rules item 10 and gate_evaluation_mode (verdicts differ -> N4)
    n4met = n4(retA, state) or n4(retB, state)
    valid_table_gate_condition = gA and gB  # S_VALID_TABLE / S_PARTIAL_TABLE require every C-BOUND gate held on both paths
    outs = set()
    if sr10: outs.add('N4 (via gate 1 / stopping_rules item 10)')
    if n4met: outs.add('N4 (condition met)')
    if valid_table_gate_condition: outs.add('C-BOUND gate condition of S_VALID_TABLE met')
    two = valid_table_gate_condition and n4met
    return {'gate1_A': gA, 'gate1_B': gB, 'stopping_rule_10_fires': sr10, 'N4_condition_met': n4met,
            'valid_table_gate_condition_met': valid_table_gate_condition, 'two_outcomes': two}
def ev_correct(state): return dict(FIXED_VALUE[state])
def ev_E0(state):   # correct under the typed text: typed bin_by_status states no bin_at_least for a NEAR_FLOOR BOUND value
    r = dict(FIXED_VALUE[state])
    if r['bin'] == 'NEAR_FLOOR': r['bin_at_least'] = None
    return r
def ev_E0_absent(state):
    r = dict(FIXED_VALUE[state])
    if r['bin'] == 'NEAR_FLOOR': del r['bin_at_least']
    return r
def ev_PTMF(state):  # wrong bin_at_least on a NEAR_FLOOR BOUND state, otherwise correct
    r = dict(FIXED_VALUE[state])
    if r['bin'] == 'NEAR_FLOOR': r['bin_at_least'] = 'INTERMEDIATE'
    return r
def ev_PTMF2(state):
    r = dict(FIXED_VALUE[state])
    if r['bin'] == 'NEAR_FLOOR': r['bin_at_least'] = 'NEAR_CEILING'
    return r
evs = {'correct_under_gated': ev_correct, 'E0 (bin_at_least null at NEAR_FLOOR BOUND)': ev_E0,
       'E0 variant (bin_at_least key absent)': ev_E0_absent, 'PTM-F (bin_at_least INTERMEDIATE)': ev_PTMF,
       'PTM-F variant (bin_at_least NEAR_CEILING)': ev_PTMF2}
evtab = []
for name, ev in evs.items():
    for s in ('BND-1', 'BND-2', 'BND-3'):
        ra = ev(s)
        evtab.append({'evaluator': name, 'state': s, 'returned': {k: v for k, v in ra.items()},
                      'under_narrow': outcomes(EXPECTED_NARROW[s], ra, ra, s),
                      'under_gated': outcomes(EXPECTED_GATED[s], ra, ra, s)})
    # path disagreement: path A correct, path B this evaluator
    for s in ('BND-1', 'BND-3'):
        ra, rb = ev_correct(s), ev(s)
        if ra != rb:
            evtab.append({'evaluator': f'path A correct, path B {name}', 'state': s,
                          'under_narrow': outcomes(EXPECTED_NARROW[s], ra, rb, s),
                          'under_gated': outcomes(EXPECTED_GATED[s], ra, rb, s)})
OUT['evaluators'] = {'table': evtab,
                     'any_two_outcomes_under_gated': any(r['under_gated']['two_outcomes'] for r in evtab),
                     'two_outcome_cases_under_narrow': sorted({(r['evaluator'], r['state']) for r in evtab if r['under_narrow']['two_outcomes']}),
                     'correct_evaluator_meets_N4_under_gated': any(r['under_gated']['N4_condition_met'] for r in evtab if r['evaluator'] == 'correct_under_gated')}

# ---------------------------------------------------------------- generic branch evaluator (PTM-A, C, D, E; RJ4 iv)
def eval_exact(b, r, m):
    ds = divisors(m); d, e = argmin_ties(b, r, ds); s = depth(b, r, e)
    return {'status': 'EXACT', 'minimiser_bits': int(d).bit_length(), 'exponent': mpmath.nstr(e, 25),
            'floor': mpmath.nstr(Fb(b, r), 25), 'ceiling': mpmath.nstr(Cb(b, r), 25), 'depth': mpmath.nstr(s, 25),
            'floor_invariant_ok': bool(e >= Fb(b, r) - mpmath.mpf(10) ** -45), **bin_fields('EXACT', s)}, d, e
def eval_bound(b, r, F, parts):
    m = r - 1 if b == 'minus' else r + 1
    assert F * sympy.prod(parts) == m
    W = set()
    for e in divisors(F):
        for k in range(len(parts) + 1):
            for S in itertools.combinations(parts, k):
                W.add(e * sympy.prod(S))
    d, ub = argmin_ties(b, r, sorted(W)); lb = Fb(b, r); s = depth(b, r, ub)
    return {'status': 'BOUND', 'witness_set_size': len(W), 'witness_bits': int(d).bit_length(),
            'upper': mpmath.nstr(ub, 25), 'lower': mpmath.nstr(lb, 25), 'depth_of_upper': mpmath.nstr(s, 25),
            **bin_fields('BOUND', s)}, d, ub, lb
ORDER = {'NEAR_CEILING': 0, 'INTERMEDIATE': 1, 'NEAR_FLOOR': 2}

# PTM-A: inert on both branches, structure of TASK-20260922-0e10d1 PTM-2 (r-1 = 2*prime, r+1 = 2^2*3*prime), 256 bits.
t0 = time.time()
qp = (2 ** 255) // 12 + 1
small = list(sympy.primerange(5, 2000))
while True:
    qp += 1
    if any(qp % p == 0 or (6 * qp - 1) % p == 0 or (12 * qp - 1) % p == 0 for p in small): continue
    if isprime(qp) and isprime(6 * qp - 1) and isprime(12 * qp - 1): break
rA = 12 * qp - 1
ptmA = {'recipe': 'least q\' > floor(2^255/12)+1 with q\', 6q\'-1, 12q\'-1 all BPSW-prime; r = 12q\'-1; r-1 = 2(6q\'-1), r+1 = 2^2*3*q\'',
