import yaml,re,collections,json
A='experiments/EXP-AUXIN-7e2e3d/amendments/'
def load(f): return yaml.safe_load(open(f))
L={'v1':load('experiments/EXP-AUXIN-7e2e3d/specification.yaml')['experiment'],
   'typed':load(A+'AMD-20260926-typed.yaml')['amendment'],
   'narrow':load(A+'AMD-20260927-narrow.yaml')['amendment'],
   'gated':load(A+'AMD-20260928-gated.yaml')['amendment']}
KEYS=('id','name','state','case','fc','item','field','path')
def walk(o,segs):
    # segs: list of sets of aliases
    if isinstance(o,dict) and o:
        for k,v in o.items(): yield from walk(v,segs+[{'.'+str(k)}])
    elif isinstance(o,list) and o:
        for i,v in enumerate(o):
            al={f' item {i+1}'}
            if isinstance(v,dict):
                for kk in KEYS:
                    if kk in v and isinstance(v[kk],(str,int)): al.add(f'[{v[kk]}]')
            yield from walk(v,segs+[al])
    else: yield segs
def aliases(segs):
    out=['']
    for s in segs:
        out=[o+a for o in out for a in s]
        if len(out)>64: out=out[:64]
    return [o[1:] if o.startswith('.') else o for o in out]
T=L['gated']['governing_text_table']
rows=[]
for r in T:
    f=r['field']; ly,_,p=f.partition(':')
    mod=None
    m=re.match(r'(.*?) (span [A-Z0-9-]+|outside span [A-Z0-9-]+|except .*)$',p)
    if m: p,mod=m.group(1),m.group(2)
    rows.append((ly,p,mod,r['layer'],f))
def covers(rp,leaf):
    return leaf==rp or leaf.startswith(rp+'.') or leaf.startswith(rp+'[') or leaf.startswith(rp+' item')
res=collections.Counter(); problems=[]; used=set()
for ly in ('v1','typed','narrow','gated'):
    for segs in walk(L[ly],[]):
        al=aliases(segs)
        hits=[r for r in rows if r[0]==ly and any(covers(r[1],a) for a in al)]
        # keep only most specific (longest path) hits
        if hits:
            mx=max(len(h[1]) for h in hits); hits2=[h for h in hits if len(h[1])==mx]
        else: hits2=[]
        for h in hits: used.add(h[4])
        mods=[h[2] for h in hits2]
        leafname=f'{ly}:{al[0]}'
        if not hits: res['uncovered']+=1; problems.append(('UNCOVERED',leafname))
        elif len(hits2)==1 and mods==[None]: res['one']+=1
        elif len(hits2)==2 and sorted(str(m)[:5] for m in mods) in (['outsi','span '],): res['span_pair']+=1
        elif any(m and m.startswith('except') for m in mods) or len(hits)>len(hits2):
            res['except_or_nested']+=1
            if len(hits)>len(hits2): problems.append(('NESTED',leafname,[h[4] for h in hits]))
        else: res['other']+=1; problems.append(('OTHER',leafname,[h[4] for h in hits2]))
print(res)
unused=[r['field'] for r in T if r['field'] not in used]
print('table rows matching no leaf:',len(unused)); print(json.dumps(unused,indent=0)[:3000])
for p in problems[:200]: print(p)

